def format_role(r):
    slug, name, title, desc, tools, tasks, faqs = r
    tools_str = ", ".join(f'"{t}"' for t in tools)
    tasks_str = ", ".join(f'"{t}"' for t in tasks)
    faq_str = ", ".join(f'{{ question: "{q}", answer: "{a}" }}' for q, a in faqs)
    long_desc = LONG_DESCRIPTIONS.get(slug, "")
    long_desc_str = f', longDescription: "{long_desc}"' if long_desc else ""
    return (
        f'  {{ slug: "{slug}", name: "{name}", title: "{title}", '
        f'description: "{desc}", '
        f'tools: [{tools_str}], '
        f'tasks: [{tasks_str}], '
        f'faq: [{faq_str}]{long_desc_str} }},'
    )

lines = ['import type { Role } from "@/types";', '', 'export const roles: Role[] = [']
for r in ROLES:
    lines.append(format_role(r))
lines.append('];')
lines.append('')

content = '\n'.join(lines)
with open('/Users/adda247/personal/shipsquad/shipsquad-front/src/data/roles.ts', 'w') as f:
    f.write(content)
print(f"Written {len(ROLES)} roles to roles.ts ({len(content)} bytes)")
